const data = $input.first().json;

const emaCurrent = data.ema_current_status || 'UNKNOWN';
const actRawCurrent = data.act_current_status || 'UNKNOWN';

// Para n8n, REBOOT y ONLINE son equivalentes: ambos indican que el Actuador está operativo
const isActuatorOperational = actRawCurrent === 'ONLINE' || actRawCurrent === 'REBOOT';
const actDisplayStatus = isActuatorOperational ? 'ONLINE' : actRawCurrent;

const lastAlert = data.last_alert_description || '';
const isBatteryAlertActive = lastAlert === 'BATERIA_AGOTADA';

let alertType = 'NONE';
let message = '';
let notifDescription = '';

// -------------------------------------------------------------------
// MÁQUINA DE ESTADOS FINITA (FSM) DE NOTIFICACIONES EMA
// Reglas estrictas:
// 1. Caso A (Batería Agotada):
//    - EMA está OFFLINE
//    - Actuador está operativo (ONLINE o REBOOT)
//    - NO hay una alerta de batería agotada previa activa en memoria/BD
//    NOTA: Si el Actuador está OFFLINE, se asume corte de luz/red y NO se notifica.
//
// 2. Caso B (Nodo EMA Operativo):
//    - EMA volvió a ONLINE o SLEEP (transmitió y durmió limpiamente)
//    - TENÍAMOS una alerta de batería agotada previa activa (Caso A)
// -------------------------------------------------------------------

if (emaCurrent === 'OFFLINE' && isActuatorOperational && !isBatteryAlertActive) {
  alertType = 'BATERIA_AGOTADA';
  notifDescription = 'BATERIA_AGOTADA';
  message = `\u200B\n<b>Batería Agotada</b>\n\n<b>Nodo EMA:</b> ${emaCurrent}\n<b>Nodo Actuador:</b> ${actDisplayStatus}\n\nEl nodo EMA se encuentra fuera de servicio.`;
} else if ((emaCurrent === 'ONLINE' || emaCurrent === 'SLEEP') && isBatteryAlertActive) {
  alertType = 'EMA_RESTABLECIDO';
  notifDescription = 'EMA_RESTABLECIDO';
  message = `\u200B\n<b>Nodo EMA Operativo</b>\n\n<b>Nodo EMA:</b> ${emaCurrent}\n<b>Nodo Actuador:</b> ${actDisplayStatus}\n\nEl nodo EMA ha restablecido la comunicación.`;
}

if (alertType === 'NONE') {
  return [];
}

return [{
  json: {
    alertType,
    message,
    notifDescription,
    emaCurrent,
    actCurrent: actDisplayStatus
  }
}];
